//! The DSBSpecFrame values that pass through C's TopoMap, checked against
//! the C library.
//!
//! `dsb_topo_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/dsb_topo_probe.c`. TopoMap (dsbspecframe.c:2051)
//! overlays the DSBSpecFrame onto a new SpecFrame, aligns it in the
//! topocentric rest frame, and converts it to a copy set to topocentric
//! frequency in Hz, so the SpecOrigin and the alignment settings take part
//! in the conversion between DSBCentre and the current system.

#[path = "dsb_topo_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{DSBSpecFrame, Frame, FrameRef, SideBand, SpecSystem, StdOfRest};

/// The probe's DSBSpecFrame, with its per-case settings and DSBCentre=230.
fn usb(name: &str) -> DSBSpecFrame {
    let mut f = DSBSpecFrame::new(SpecSystem::Freq);
    Frame::set_unit(&mut f, 1, "GHz").unwrap();
    f.set_std_of_rest(StdOfRest::Lsrk).unwrap();
    f.set_epoch_year(2005.0);
    f.set_if_ghz(4.0);
    f.set_sideband(SideBand::USB);
    f.set_align_sideband(true);
    f.set_ref_pos(None, 2.6, 0.35).unwrap();
    let spec = f.spec_mut();
    match name {
        "plain" => {}
        "origin" => spec.set_spec_origin_cur(229.0).unwrap(),
        "align_bary" => spec.set_align_std_of_rest(StdOfRest::Barycentric),
        "origin_align_offset" => {
            spec.set_spec_origin_cur(229.0).unwrap();
            spec.set_align_spec_offset(true);
        }
        "origin_align_bary" => {
            spec.set_spec_origin_cur(229.0).unwrap();
            spec.set_align_std_of_rest(StdOfRest::Barycentric);
        }
        other => panic!("no Rust set-up for case {other}"),
    }
    f.set_dsb_centre_cur(230.0).unwrap();
    f
}

fn to_lsb(usb: &DSBSpecFrame) -> Option<[f64; 2]> {
    let mut lsb = usb.clone();
    lsb.set_sideband(SideBand::LSB);
    let fs = usb.convert_to(&lsb, &[]).ok()??;
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).ok()?;
    let pts = PointSet::from_columns(&[&cases::POINTS[..]]).unwrap();
    let out = map.transform(&pts, true).ok()?;
    Some([out.point(0)[0], out.point(1)[0]])
}

/// Cases the port does not yet reproduce, each with what would close it.
/// `excluded_cases_still_differ` fails when one starts matching.
const DSB_TOPO_EXCLUDED: &[(&str, &str)] = &[(
    "origin_align_offset",
    "C cannot convert between the sidebands. Its SpecFrame SubFrame sets \
     the StdOfRest of the alignment Frame, whose SpecOrigin \
     OriginStdOfRest re-expresses through a conversion between rest frames \
     (specframe.c:3191). With AlignSpecOffset set in a wavelength System \
     that conversion maps every value to bad in C, a SpecFrame matter \
     rather than a DSBSpecFrame one, so C reports AST__ATSER; the port's \
     conversion keeps finite values (audit DSB-5, SPEC_ORIGIN_SOR_EXCLUDED \
     in test_spec_origin_sor.rs)",
)];

fn observed(name: &str) -> (Option<f64>, Option<f64>, Option<[f64; 2]>) {
    let f = usb(name);
    (f.dsb_centre_cur().ok(), f.imag_freq_ghz().ok(), to_lsb(&f))
}

#[test]
fn topocentric_conversions_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, centre, imag, lsb) in cases::CASES {
        if DSB_TOPO_EXCLUDED.iter().any(|(n, _)| *n == name) {
            continue;
        }
        let got = observed(name);
        if got != (centre, imag, lsb) {
            failures.push(format!(
                "{name}: got {got:?}, C gives {:?}",
                (centre, imag, lsb)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Every `DSB_TOPO_EXCLUDED` entry names a case that still differs from C.
#[test]
fn excluded_cases_still_differ() {
    for (name, why) in DSB_TOPO_EXCLUDED {
        let &(_, centre, imag, lsb) = cases::CASES
            .iter()
            .find(|c| c.0 == *name)
            .unwrap_or_else(|| panic!("{name} is excluded but not a case"));
        assert_ne!(
            observed(name),
            (centre, imag, lsb),
            "{name} now matches C; remove it from DSB_TOPO_EXCLUDED ({why})"
        );
    }
}
